"""角色静态基础信息快照常量：行迹（满级）与星魂（全 6 层）。

数据源：官方 wiki 角色词条详情（channel 18，rpg 模块的行迹/星魂模块），
解析后固化为常量；行迹仅存满级行数值（tableData 末行），效果描述为官方
原文剥标签透传（含【】梯度标记不清洗——展示原样）。

索引键 = 游戏内部角色数字 id（avatarId，与 character_const.Character.avatar_id
同源；权威表双源锚定）。账号运行时的星魂/行迹（含解锁与练度状态）走
mys_get_roster_detail（SrRank/SrSkill），本模块是**全量静态定义**（不随账号变）。

版本刷新：游戏新版本后重跑 wiki 角色详情抓取（脚本在私有 skill
sr-od-dev-avatar-extract/scripts/）→ 重新生成本模块 → 人工审阅 diff。

模块纪律：零外部 IO、零状态——纯常量（同 sr_relic_sets 模块纪律）。
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class CharacterTraceDef:
    """行迹节点（满级口径）。

    Attributes:
        tag: 行迹类型官方中文（普攻/战技/终结技/天赋/秘技/属性加成/额外能力/欢愉技）.
        name: 行迹名。
        max_level: 满级等级文本（如「等级12」）。
        max_values: 满级行数值（tableData 末行，顺序对齐 headers 数值列）。
        desc: 效果描述（官方原文剥 HTML 透传，含【】梯度标记）。
    """

    tag: str
    name: str
    max_level: str
    max_values: tuple[str, ...]
    desc: str


@dataclass(frozen=True)
class CharacterEidolonDef:
    """星魂层（官方原文透传）。

    Attributes:
        pos: 星魂序号 1-6（坐标系：星魂第 N 层，恒稳）。
        name: 星魂名。
        desc: 效果描述（官方原文剥 HTML 透传）。
    """

    pos: int
    name: str
    desc: str


