        CharacterTraceDef('终结技', '|账号已封禁|', '等级12', ('103%', '46%', '410%'), '有【85%/100%】的基础概率使指定敌方单体防御力降低【36%/45%】，持续3回合，同时对该目标造成等同于银狼【228%/380%】攻击力的量子属性伤害。'),
        CharacterTraceDef('天赋', '等待程序响应...', '等级12', ('11.0%', '8.8%', '6.6%', '74%'), '银狼能够制造：攻击力降低【5%/10%】、防御力降低【4%/8%】、速度降低【3%/6%】3种【缺陷】。\n银狼每次施放攻击后有【60%/72%】的基础概率给受到攻击的敌方目标植入1个随机【缺陷】，持续3回合。'),
        CharacterTraceDef('秘技', '|强制结束进程|', '数值1', (), '立即攻击敌人，进入战斗后对敌方全体造成等同于银狼80%攻击力的量子属性伤害，并无视弱点属性削减敌方全体的韧性，击破弱点时，触发量子属性的弱点击破效果。'),
        CharacterTraceDef('额外能力', '生成', '数值1', (), '【缺陷】的持续时间增加1回合。每当有敌方目标的弱点被击破时,银狼有65%的基础概率对该目标植入1个随机【缺陷】。'),
        CharacterTraceDef('额外能力', '注入', '数值1', (), '施放战技时，为敌方目标添加的弱点持续时间增加1回合。'),
        CharacterTraceDef('额外能力', '旁注', '数值1', (), '施放战技时，若敌方目标的负面效果数量大于等于3个，则战技使目标全属性抗性降低的效果额外降低3%。'),
