        CharacterTraceDef('战技', '禁锢解除', '等级12', ('264%',), '消耗等同于阿兰生命上限15%的生命值对指定敌方单体造成等同于阿兰【120%/240%】攻击力的雷属性伤害。若当前生命值不足，施放战技时阿兰的当前生命值降至1点。'),
