        CharacterTraceDef('战技', '流星群落', '等级12', ('55%', '55%'), '对指定敌方单体造成等同于艾丝妲【25%/50%】攻击力的火属性伤害，并额外施放4次炮击。每次炮击对敌方随机单体造成等同于艾丝妲【25%/50%】攻击力的火属性伤害。'),
