        CharacterTraceDef('战技', '伪•螺旋剑/结束', '等级12', ('396%', '108%'), '进入【回路连接】状态。对指定敌方单体造成等同于Archer【180%/360%】攻击力的量子属性伤害。【回路连接】状态下施放战技后，本回合不会结束，并使Archer战技造成的伤害提高【60%/100%】，该效果可以叠加2层，持续至退出【回路连接】状态。主动施放5次战技后或战技点不足以再次施放战技则退出【回路连接】状态。每个波次中的所有敌方目标被消灭后会退出【回路连接】状态。\n退出【回路连接】状态，并结束回合。'),
