        CharacterTraceDef('战技', '史瓦罗在看着你', '等级12', ('132%',), '对敌方全体造成等同于克拉拉【60%/120%】攻击力的物理属性伤害，并对所有被史瓦罗标上【反击标记】的敌方目标额外造成等同于克拉拉【60%/120%】攻击力物理属性伤害。\n战技施放后所有【反击标记】失效。'),
        CharacterTraceDef('终结技', '是约定不是命令', '等级12', ('27%', '172%'), '施放终结技后克拉拉受到的伤害额外降低【15%/25%】且被敌方目标攻击的概率大幅提高，持续2回合。\n同时史瓦罗的反击得到强化，当任意我方目标受到攻击后史瓦罗立即施放反击，对敌方目标造成的伤害倍率提高【96%/160%】，并对其相邻目标造成相当于主目标50%的伤害。强化效果可生效2次。'),
        CharacterTraceDef('天赋', '因为我们是家人', '等级12', ('176%',), '克拉拉在史瓦罗的保护下受到敌方目标攻击的伤害降低10%。攻击克拉拉的敌方目标会被史瓦罗标上【反击标记】，并遭到史瓦罗的反击，对其造成等同于克拉拉【80%/160%】攻击力的物理属性伤害。'),
        CharacterTraceDef('秘技', '胜利的小小代价', '数值1', (), '立即攻击敌人，进入战斗后克拉拉受到敌方攻击的概率提高，持续2回合。'),
        CharacterTraceDef('额外能力', '家人', '数值1', (), '受到攻击时有35%的固定概率解除自身1个负面效果。'),
