        CharacterTraceDef('战技', '遥击三尺水', '等级12', ('242%',), '对指定敌方单体造成等同于彦卿【110%/220%】攻击力的冰属性伤害，并为彦卿附加【智剑连心】，持续1回合。'),
        CharacterTraceDef('终结技', '快雨燕相逐', '等级12', ('54%', '378%'), '提高自身60%暴击率，若彦卿处于【智剑连心】效果，则使其暴击伤害额外提高【30%/50%】，增益效果持续1回合。随后对指定敌方单体造成等同于彦卿【210%/350%】攻击力的冰属性伤害。'),
        CharacterTraceDef('天赋', '呼剑如影', '等级12', ('21.0%', '33%', '62%', '55%', '55%'), '彦卿处于【智剑连心】效果时，受到攻击的概率降低，并为自身提高【15.0%/20.0%】暴击率和【15%/30%】暴击伤害。对敌方目标施放攻击后，有【50%/60%】的固定概率发动追加攻击，对目标造成等同于彦卿【25%/50%】攻击力的冰属性伤害，并有65%的基础概率使其陷入冻结状态，持续1回合。\n冻结状态下，敌方目标不能行动，同时每回合开始时受到等同于彦卿【25%/50%】攻击力的冰属性附加伤害。\n当彦卿受到伤害后，【智剑连心】将会消失。'),
        CharacterTraceDef('秘技', '御剑真诀', '数值1', (), '使用秘技后，下一次战斗开始时彦卿对当前生命值百分比大于等于50%的敌方目标造成的伤害提高30%，持续2回合。'),
        CharacterTraceDef('额外能力', '颁冰', '数值1', (), '施放攻击后，对携带冰属性弱点的敌方目标造成等同于彦卿30%攻击力的冰属性附加伤害。'),
