        CharacterTraceDef('战技', '迎面开门红', '等级12', ('132%', '44%', '240%'), '对指定敌方单体造成等同于桂乃芬【60%/120%】攻击力的火属性伤害，并对相邻目标造成等同于桂乃芬【20%/40%】攻击力的火属性伤害，有100%的基础概率使目标与相邻目标陷入灼烧状态。灼烧状态下，敌方目标每回合开始时受到等同于桂乃芬【83%/218%】攻击力的火属性持续伤害，持续2回合。'),
        CharacterTraceDef('终结技', '给您来段看家戏', '等级12', ('129.6%', '96%'), '对敌方全体造成等同于桂乃芬【72.0%/120.0%】攻击力的火属性伤害，若目标处于灼烧状态，使其当前承受的灼烧状态立即产生相当于原伤害【72%/92%】的伤害。'),
        CharacterTraceDef('天赋', '古来君子养艺人', '等级12', ('7.6%',), '桂乃芬在场时，敌方受到的灼烧状态触发伤害后，有100%的基础概率陷入【吞火】状态，【吞火】状态下敌方目标受到的伤害提高【4.0%/7.0%】，持续3回合，最多叠加3层。'),
