        CharacterTraceDef('普攻', '望、闻、问…蹴！', '等级7', ('110%',), '对指定敌方单体造成等同于白露【50%/100%】攻击力的雷属性伤害。'),
        CharacterTraceDef('战技', '云吟乍涌坠珠露', '等级12', ('12.4%', '347'), '立即为指定我方单体回复等同于白露【7.8%/11.7%】生命上限+【78/312】的生命值，然后白露随机为我方单体进行2次治疗，每提供1次治疗，下一次治疗回复的生命值会降低15%。'),
        CharacterTraceDef('终结技', '匏蛟跃渊先雷音', '等级12', ('14.4%', '400'), '立即为我方全体回复等同于白露【9.0%/13.5%】生命上限+【90/360】生命值。\n对于没有【生息】的我方目标，白露使其附上【生息】，对于已拥有【生息】的我方目标，白露使其已有的【生息】持续时间延长1回合。\n【生息】可持续2回合，该效果不可叠加。'),
        CharacterTraceDef('天赋', '奔走悬壶济世长', '等级12', ('5.7%', '160', '19.2%', '534'), '拥有【生息】的我方目标，在受到攻击后会回复等同于白露【3.6%/5.4%】生命上限+【36/144】的生命值，该效果可以触发2次。\n当白露的队友受到致命攻击时，不会陷入无法战斗状态，白露会立即为其提供治疗，回复等同于白露【12.0%/18.0%】生命上限+【120/480】的生命值。该效果单场战斗中可以触发1次。'),
        CharacterTraceDef('秘技', '徜徉灵泽病恙短', '数值1', (), '使用秘技后，下一次战斗开始时为我方全体附上【生息】，持续2回合。'),
        CharacterTraceDef('额外能力', '岐黄精义', '数值1', (), '白露对我方目标造成过量治疗时会提高目标10%的生命上限，持续2回合。'),
        CharacterTraceDef('额外能力', '持明龙脉', '数值1', (), '【生息】效果的触发次数增加1次。'),
        CharacterTraceDef('额外能力', '鳞渊福泽', '数值1', (), '拥有【生息】的角色受到的伤害降低10%。'),
        CharacterTraceDef('属性加成', '生命强化', '数值1', (), '生命值上限提高4.0%'),
