        CharacterTraceDef('欢愉技', '举杯！敬炽烈一夏/All in！敬炽烈一夏', '等级12', ('66%', '19.8%', '23.1%'), '对敌方全体造成【30%/60%】量子属性欢愉伤害，并额外造成10次伤害，每次伤害对随机敌方单体造成【9%/18%】量子属性欢愉伤害。\n对敌方全体造成【30%/60%】量子属性欢愉伤害，并额外造成10次伤害，每次伤害对随机敌方单体造成【9%/18%】量子属性欢愉伤害。施放时会消耗所有【热意】，每消耗1点【热意】都会额外对随机敌方单体造成1次【10.5%/21%】量子属性欢愉伤害。'),
        CharacterTraceDef('忆灵天赋', '', '等级7', (), ''),
