        CharacterTraceDef('忆灵技', '坏人！麻烦！/我会！帮你！', '等级7', ('39.6%', '99%', '30%'), '造成 4 次伤害，每次对敌方随机单体造成等同于迷迷 【18%/36%】 攻击力的冰属性伤害。最后对敌方全体造成等同于迷迷【45%/90%】 攻击力的冰属性伤害。\n使指定我方单体行动提前 100% 并附上【迷迷的声援】，持续 3 回合。\n持有【迷迷的声援】的目标每造成1次伤害，都会再额外造成1次等同于原伤害 【18%/28%】 的真实伤害。\n当对自身施放该技能时，无法触发行动提前效果。'),
        CharacterTraceDef('忆灵天赋', '伙伴！一起！/迷迷，加油！/遗憾…不留', '等级7', ('13.2%', '26.4%'), '使我方全体的暴击伤害提高，提高数值等同于迷迷【6%/12%】暴击伤害+【12%/24%】。\n若充能未达到 100% ，迷迷行动时自动施放【坏人！麻烦！】。充能达到 100% 时迷迷立即行动，下一次行动时能够选择我方单体并施放【我会！帮你！】。\n迷迷被召唤时，立即获得 50% 充能。\n迷迷消失时，使开拓者行动提前 25% 。'),
