        CharacterTraceDef('终结技', '放心飞，开拓永相随！', '等级12', ('54%',), '获得5个笑点，使指定我方单体暴击伤害提高【30%/50%】，持续3回合，并解除该目标的控制类负面状态。\n若目标拥有欢愉技，目标额外获得10点【好活当赏】，并使其立即施放1次固定计入20笑点的欢愉技，若欢愉技施放前敌方目标被消灭则对新入场的敌方目标发动欢愉技。\n若目标不拥有欢愉技，使其行动提前50%。'),
