        CharacterEidolonDef(4, '完全剖析', '施放战技时，有100%的基础概率使敌方目标冰属性抗性降低12%，持续2回合。'),
        CharacterEidolonDef(5, '零度妨害', '终结技等级+2，最多不超过15级；天赋等级+2，最多不超过15级。'),
        CharacterEidolonDef(6, '疲弱追击', '施放攻击后，若敌方目标处于负面效果，则对其造成等同于佩拉40%攻击力的冰属性附加伤害。'),
