        CharacterEidolonDef(2, '紧紧的拥抱', '施放终结技后攻击力提高30%，持续2回合。'),
        CharacterEidolonDef(3, '冰冷的钢甲', '战技等级+2，最多不超过15级；普攻等级+1，最多不超过10级。'),
        CharacterEidolonDef(4, '家人的温暖', '受到攻击后，克拉拉受到的伤害降低30%，效果持续到自己的下个回合开始。'),
        CharacterEidolonDef(5, '小小的承诺', '终结技等级+2，最多不超过15级；天赋等级+2，最多不超过15级。'),
        CharacterEidolonDef(6, '长久的陪伴', '我方其他目标遭到攻击后，史瓦罗也有50%的固定概率触发对攻击者的反击，并对攻击目标添加【反击标记】。施放终结技时，额外增加1次强化反击的次数。'),
