        CharacterEidolonDef(2, '吃好喝好长身体', '战技使敌方目标陷入的灼烧状态持续时间增加1回合。'),
        CharacterEidolonDef(3, '不挑不选全都要', '战技等级+2，最多不超过15级；普攻等级+1，最多不超过10级。'),
        CharacterEidolonDef(4, '稀里糊涂没关系', '触发天赋时，有100%基础概率使指定敌方目标的相邻目标也陷入等同于战技的灼烧状态。'),
        CharacterEidolonDef(5, '好事留名鼹鼠党', '终结技等级+2，最多不超过15级；天赋等级+2，最多不超过15级。'),
