def resolve_traces(avatar_id: int) -> tuple[CharacterTraceDef, ...]:
    """角色数字 id → 行迹定义（miss 返回空元组，不抛异常）。"""
    return CHARACTER_TRACES.get(avatar_id, ())


def resolve_eidolons(avatar_id: int) -> tuple[CharacterEidolonDef, ...]:
    """角色数字 id → 星魂定义（miss 返回空元组，不抛异常）。"""
    return CHARACTER_EIDOLONS.get(avatar_id, ())

